using InovaGed.Environment.Doctor.Quality; using Npgsql;
namespace InovaGed.Environment.Doctor.Checks;
public sealed class PostgresSchemaQualityCheck:IQualityCheck {public string Name=>"Banco de dados";private static readonly string[] Tables=["label_template","label_template_config","label_template_field","label_template_version","label_print","label_print_history","label_print_job","label_print_job_item","locdesk_label_draft","classification_plan","classification_plan_version","document_classification","retention_destination_batch","retention_destination_item","retention_hold","box","physical_location","batch_item","ai_tenant_policy","ai_monthly_usage","ai_execution","ai_suggestion_application","ai_retention_recalc_pending"];
 private static readonly Dictionary<string,string[]> Columns=new(){{"label_template",["id","tenant_id","code","name","description","print_mode","subject_type","view_name","version","is_system_template","is_custom_template","is_active","is_default","supports_batch","allows_manual_fields","display_order","reg_status"]},{"classification_plan",["id","tenant_id","code","title","description","final_destination","reg_status"]},{"document",["classification_id","retention_basis_at","retention_due_at","retention_status"]},{"ai_execution",["id","tenant_id","user_id","task","state","input_fingerprint","reservation_period","result_json","result_expires_at","source_documents","usage_reconciled_at","reconciled_delta"]},{"ai_suggestion_application",["id","tenant_id","execution_id","document_id","version_id","task","reviewer_id","decision_fingerprint","decision_json","outcome","partial","operation_key"]},{"ai_retention_recalc_pending",["id","tenant_id","document_id","application_id","reason","resolved_at","attempts","last_error","claimed_at","claim_token","next_attempt_at"]}};
 public async Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){if(c.NoDatabaseRequired||string.IsNullOrWhiteSpace(c.ConnectionString))return[new(Name,QualityStatus.Warning,"Banco não configurado; schema PostgreSQL não foi consultado.","Checks estáticos continuam ativos.","Forneça ConnectionStrings__DefaultConnection para validação completa.")];var r=new List<QualityFinding>();try{await using var db=new NpgsqlConnection(c.ConnectionString);await db.OpenAsync(ct);await using var cmd=new NpgsqlCommand("select table_name,column_name from information_schema.columns where table_schema='ged'",db);await using var rd=await cmd.ExecuteReaderAsync(ct);var map=new Dictionary<string,HashSet<string>>(StringComparer.OrdinalIgnoreCase);while(await rd.ReadAsync(ct)){var t=rd.GetString(0);if(!map.TryGetValue(t,out var set))map[t]=set=new(StringComparer.OrdinalIgnoreCase);set.Add(rd.GetString(1));}foreach(var t in Tables)r.Add(map.ContainsKey(t)?new(Name,QualityStatus.Pass,$"Tabela presente: ged.{t}"):Missing($"Tabela ausente: ged.{t}"));foreach(var pair in Columns)foreach(var col in pair.Value)r.Add(map.TryGetValue(pair.Key,out var set)&&set.Contains(col)?new(Name,QualityStatus.Pass,$"Coluna presente: ged.{pair.Key}.{col}"):Missing($"Coluna ausente: ged.{pair.Key}.{col}"));}catch(Exception e){r.Add(new(Name,QualityStatus.Fail,$"Falha ao consultar PostgreSQL: {e.GetType().Name}","Schema não foi certificado.","Verificar conectividade e credenciais; não exponha a senha.","database/apply_all_required_migrations.sql"));}return r;}private QualityFinding Missing(string m)=>new(Name,QualityStatus.Fail,m,"Funcionalidade dependente pode retornar 500.","Aplicar migrations obrigatórias.","database/apply_all_required_migrations.sql");}
